import type { BankQuestion } from "@/lib/bank";

/** Evolution (Biology (NEET)): 100 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-evolution-1","question":"The theory that life arose from non-living molecules in a reducing atmosphere (chemical evolution) was proposed by:","options":["Oparin and Haldane","Louis Pasteur","Darwin and Wallace","Hugo de Vries"],"answer":0,"explanation":"Oparin and Haldane proposed that the first forms of life arose from pre-existing non-living organic molecules through chemical evolution in a reducing (no free O₂) atmosphere.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-evolution-2","question":"In Stanley Miller's 1953 experiment, electric discharge was passed through a closed flask containing:","options":["CH₄, H₂, NH₃ and water vapour at 800 °C","CO₂, O₂, N₂ and water vapour at 100 °C","CH₄, O₂ and H₂S at 800 °C","NH₃, O₂ and water vapour at 37 °C"],"answer":0,"explanation":"Miller simulated the early atmosphere with methane, hydrogen, ammonia and water vapour at 800 °C and observed formation of amino acids, supporting chemical evolution.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-evolution-3","question":"Organs that are anatomically similar but perform different functions, such as the forelimbs of whale, bat and human, are:","options":["Analogous organs","Vestigial organs","Homologous organs","Convergent organs"],"answer":2,"explanation":"Homologous organs share a common ancestral structure (same bones in the same order) even though their functions differ; this is divergent evolution.","difficulty":"easy"},
  {"id":"bio-evolution-4","question":"The wings of a butterfly and the wings of a bird are an example of:","options":["Homology and divergent evolution","Genetic drift","Adaptive radiation","Analogy and convergent evolution"],"answer":3,"explanation":"They are anatomically different structures performing the same function (flight), so they are analogous, the result of convergent evolution. Other examples: eye of octopus and mammals, flippers of penguins and dolphins.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-5","question":"Industrial melanism in the peppered moth (Biston betularia) demonstrates:","options":["Natural selection","Mutation theory of de Vries","Inheritance of acquired characters","Genetic drift"],"answer":0,"explanation":"After industrialisation blackened tree trunks, dark moths were better camouflaged from predators and increased, while light moths declined; selection, not mutation induced by soot, changed the frequencies.","difficulty":"moderate"},
  {"id":"bio-evolution-6","question":"According to the Hardy-Weinberg principle, the sum of allele frequencies p + q equals 1 and the genotype frequencies are given by:","options":["p + 2pq + q = 1","p² + 2pq + q² = 1","p² + pq + q² = 1","2p + 2q = 1"],"answer":1,"explanation":"For two alleles with frequencies p and q, the genotypes AA, Aa and aa occur at p², 2pq and q², which sum to (p + q)² = 1 when the population is in equilibrium.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-7","question":"Archaeopteryx is regarded as a connecting link between:","options":["Fishes and amphibians","Amphibians and reptiles","Reptiles and birds","Reptiles and mammals"],"answer":2,"explanation":"Archaeopteryx shows feathers and wings like birds together with teeth, claws on the wings and a long bony tail like reptiles.","difficulty":"moderate"},
  {"id":"bio-evolution-8","question":"The first cellular forms of life on Earth appeared about:","options":["4.5 billion years ago","3 billion years ago","2000 million years ago","500 million years ago"],"answer":2,"explanation":"Earth formed about 4.5 billion years ago, non-cellular forms (giant molecules of RNA, protein, polysaccharides) about 3 billion years ago, and the first cellular forms about 2000 million years ago.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-9","question":"Darwin's finches of the Galapagos Islands, with varied beaks adapted to different foods, illustrate:","options":["Convergent evolution","Artificial selection","Genetic drift","Adaptive radiation"],"answer":3,"explanation":"Adaptive radiation is the evolution of different species from a common ancestor within a geographical area, each adapted to a different habitat or diet; Australian marsupials are another example.","difficulty":"moderate"},
  {"id":"bio-evolution-10","question":"In a population in Hardy-Weinberg equilibrium, 16% of individuals show a recessive phenotype. The frequency of heterozygotes is:","options":["0.16","0.36","0.48","0.84"],"answer":2,"explanation":"q² = 0.16, so q = 0.4 and p = 0.6. Heterozygotes = 2pq = 2 × 0.6 × 0.4 = 0.48. (Dominant phenotype in total = 0.84.)","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-11","question":"Which hominid had a cranial capacity of about 900 cc and probably ate meat?","options":["Homo erectus","Homo habilis","Neanderthal man","Australopithecus"],"answer":0,"explanation":"Homo erectus (about 1.5 mya) had a large brain of around 900 cc and probably ate meat. Homo habilis had 650-800 cc and probably did not eat meat; Neanderthals had about 1400 cc.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-12","question":"When selection favours individuals of both extreme phenotypes over the mean, the population shows:","options":["Stabilising selection","Directional selection","Disruptive selection","Artificial selection"],"answer":2,"explanation":"Disruptive selection increases both peripheral types, producing a bimodal distribution. Stabilising selection favours the mean (variation shrinks); directional selection shifts the peak in one direction.","difficulty":"hard"},
  {"id":"bio-evolution-13","question":"Which pair represents analogous organs?","options":["Thorn of Bougainvillea and tendril of Cucurbita","Vertebrate hearts and brains","Sweet potato (root) and potato (stem)","Forelimbs of whale and bat"],"answer":2,"explanation":"Sweet potato (modified root) and potato (modified stem) are different organs performing the same storage function: analogy. The other three pairs are homologous.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-14","question":"The change in allele frequency in a new population founded by a few migrants that differs markedly from the parent population is called:","options":["Gene flow","Stabilising selection","Founder effect","Saltation"],"answer":2,"explanation":"The founder effect is a form of genetic drift: when a small sample starts a new population, chance alone gives it allele frequencies different from the original and the new population may become a different species.","difficulty":"hard"},
  {"id":"bio-evolution-15","question":"Hugo de Vries, working on evening primrose, proposed that evolution occurs by:","options":["Slow accumulation of minor variations","Inheritance of acquired characters","Use and disuse of organs","Large single-step mutations (saltation)"],"answer":3,"explanation":"de Vries believed mutations are large, random and directionless, causing speciation in single steps (saltation), unlike Darwin's gradual minor variations.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-16","question":"In the geological record, lobefins are important because:","options":["They evolved into the first amphibians","They gave rise to the first reptiles","They were the first jawless fish","They became the first mammals"],"answer":0,"explanation":"Some fish with stout, strong fins could move on land and go back to water (about 350 mya); these lobefins evolved into the first amphibians. A living lobefin, the coelacanth, was caught in South Africa in 1938.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-17","question":"The appearance of DDT-resistant mosquitoes within a few years of spraying is best explained as:","options":["Mutation induced by DDT in each exposed individual","Natural selection of pre-existing resistant variants (anthropogenic selection)","Inheritance of resistance acquired during life","Genetic drift in a small population"],"answer":1,"explanation":"Resistant variants already present in the population survived and reproduced, so resistance spread in years rather than centuries. DDT selected the variants; it did not create them in each individual.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-18","question":"Louis Pasteur's swan-necked flask experiment established that:","options":["Life arises spontaneously from decaying matter","Micro-organisms are formed by chemical evolution","Amino acids form under reducing conditions","Life comes only from pre-existing life"],"answer":3,"explanation":"Killed yeast in a sealed flask produced no life, while an open flask did; this dismissed spontaneous generation and showed life arises from pre-existing life.","difficulty":"hard"},
  {"id":"bio-evolution-19","question":"How many of the following statements about Miller's experiment are correct?\n(i) It was performed in 1953.\n(ii) Electric discharge was used as the energy source.\n(iii) The temperature maintained was 800 °C.\n(iv) Free oxygen was included to mimic the early atmosphere.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is wrong: the early atmosphere was reducing with no free oxygen; the flask held CH₄, H₂, NH₃ and water vapour.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-20","question":"Assertion (A): The wing of a bat and the wing of a butterfly are analogous organs.\nReason (R): They are anatomically dissimilar structures that have evolved to perform the same function.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R is the definition of analogy: different structures, same function, through convergent evolution. (Bat wing and human forelimb would be homologous.)","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-21","question":"Arrange the following in the correct chronological order of appearance: (i) Homo erectus (ii) Australopithecus (iii) Dryopithecus (iv) Neanderthal man (v) Homo habilis","options":["(iii), (ii), (v), (i), (iv)","(ii), (iii), (v), (i), (iv)","(iii), (ii), (i), (v), (iv)","(iii), (v), (ii), (i), (iv)"],"answer":0,"explanation":"Dryopithecus (about 15 mya) → Australopithecus (about 2 mya) → Homo habilis → Homo erectus (about 1.5 mya) → Neanderthal (100,000-40,000 years ago) → Homo sapiens.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-22","question":"In a population of 2000 individuals in Hardy-Weinberg equilibrium, the frequency of the recessive allele is 0.3. The expected number of heterozygotes is:","options":["420","840","180","980"],"answer":1,"explanation":"q = 0.3, p = 0.7. Heterozygote frequency 2pq = 2 × 0.7 × 0.3 = 0.42; 0.42 × 2000 = 840 individuals. (Homozygous recessive would be 0.09 × 2000 = 180.)","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-23","question":"Match the scientist with the idea.\nList I: (A) Lamarck (B) Darwin and Wallace (C) Hugo de Vries (D) Oparin and Haldane\nList II: (1) Mutation theory (2) Chemical evolution (3) Inheritance of acquired characters (4) Natural selection","options":["A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2","A-3, B-1, C-4, D-2","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Lamarck: use and disuse with inheritance of acquired characters (giraffe neck); Darwin and Wallace: natural selection; de Vries: mutation theory; Oparin and Haldane: chemical origin of life.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-24","question":"How many of the following statements about the history of life are correct?\n(i) Sea weeds and a few plants existed about 320 million years ago.\n(ii) Dinosaurs disappeared about 65 million years ago.\n(iii) Tyrannosaurus rex was about 20 feet in height.\n(iv) The first mammals were like shrews.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT statements: plants about 320 mya, dinosaur extinction about 65 mya, T. rex about 20 ft tall with dagger-like teeth, and shrew-like early mammals.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-25","question":"Which statement about types of natural selection is INCORRECT?","options":["In stabilising selection more individuals acquire the mean character value and variation is reduced","In directional selection the peak of the distribution shifts in one direction","In disruptive selection the distribution becomes bimodal","In stabilising selection the peak shifts towards one extreme"],"answer":3,"explanation":"Stabilising selection keeps the peak at the mean and narrows the curve; it is directional selection that moves the peak to one side. Disruptive selection favours both extremes, giving two peaks.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-26","question":"How many of the following statements about human evolution are correct?\n(i) Homo habilis had a brain capacity of 650-800 cc and probably did not eat meat.\n(ii) Neanderthal man lived in east and central Asia 100,000 to 40,000 years ago and buried the dead.\n(iii) Homo sapiens arose in Africa and moved across continents.\n(iv) Prehistoric cave art developed about 18,000 years ago.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are NCERT facts; agriculture came about 10,000 years back and human settlements followed. Neanderthals (about 1400 cc) used hides to protect their bodies.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-27","question":"Which of the following does NOT disturb Hardy-Weinberg equilibrium?","options":["Gene migration","Genetic drift","Random mating","Natural selection"],"answer":2,"explanation":"Random mating is a condition of the equilibrium. The five factors that disturb it are gene migration (gene flow), genetic drift, mutation, genetic recombination and natural selection.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-28","question":"Match the Australian marsupial with its convergent placental counterpart.\nList I: (A) Numbat (B) Tasmanian wolf (C) Flying phalanger (sugar glider) (D) Spotted cuscus\nList II: (1) Flying squirrel (2) Lemur (3) Anteater (4) Wolf","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"answer":0,"explanation":"Numbat is the marsupial anteater, the Tasmanian wolf parallels the wolf, the sugar glider the flying squirrel and the spotted cuscus the lemur: placental mammals and marsupials evolved similar forms convergently in different continents.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-29","question":"How many of the following statements about the early Earth are correct?\n(i) The early Earth had no atmosphere.\n(ii) Water vapour, methane, carbon dioxide and ammonia released from the molten mass covered the surface.\n(iii) UV rays from the Sun split water into hydrogen and oxygen; the lighter H₂ escaped.\n(iv) Oxygen combined with ammonia and methane to form water, CO₂ and other compounds, and an ozone layer formed.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four describe the NCERT account of the early Earth; as it cooled, the water vapour fell as rain and filled depressions to form the oceans.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-30","question":"Assertion (A): Fitness, in the Darwinian sense, refers to reproductive fitness.\nReason (R): Those organisms that are better adapted to their environment leave more progeny, and the characteristics that make them fit are heritable.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: Darwin's key insight was that fitness is measured by reproductive success of heritable variations, and over time the better-adapted forms become selected by nature.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-31","question":"The Big Bang theory attempts to explain the origin of:","options":["The first cell","The universe","Amino acids in Miller's experiment","Multicellular animals"],"answer":1,"explanation":"The Big Bang theory describes a huge explosion that formed the universe; the Earth is believed to have formed about 4.5 billion years ago.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-evolution-32","question":"The age of fossils, and hence of the rock layers in which they are found, is determined by:","options":["Carbon dioxide measurement","Radioactive dating","Comparing body sizes","Counting annual rings"],"answer":1,"explanation":"Different-aged rock sediments contain fossils of different life forms; their ages are found by radioactive dating.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-33","question":"According to the idea of panspermia, life came to Earth from outer space as units called:","options":["Microspheres","Coacervates","Protobionts","Spores"],"answer":3,"explanation":"Some scientists believe that units of life called spores were transferred to different planets, including Earth; this is panspermia.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-34","question":"The two key concepts of Darwin's theory of evolution are:","options":["Use and disuse of organs","Saltation and mutation","Inheritance of acquired characters and spontaneous generation","Branching descent and natural selection"],"answer":3,"explanation":"Darwin's theory rests on branching descent and natural selection. Use and disuse and inheritance of acquired characters were Lamarck's ideas; saltation was de Vries's.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-35","question":"Agriculture and human settlements started about:","options":["18,000 years ago","75,000 years ago","2 million years ago","10,000 years ago"],"answer":3,"explanation":"During the ice age between 75,000 and 10,000 years ago modern Homo sapiens arose; pre-historic cave art developed about 18,000 years ago and agriculture began around 10,000 years ago.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-36","question":"Neanderthal man, with a brain size of about 1400 cc, lived in the near east and central Asia between:","options":["10,000 and 5,000 years ago","2 million and 1.5 million years ago","15 and 10 million years ago","1,00,000 and 40,000 years ago"],"answer":3,"explanation":"Neanderthals lived between 1,00,000 and 40,000 years ago, used hides to protect their bodies and buried their dead.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-37","question":"A coelacanth, a lobefin fish thought to be extinct, was caught in 1938 in:","options":["Australia","Madagascar's lakes","Galapagos Islands","South Africa"],"answer":3,"explanation":"The coelacanth was caught in South Africa in 1938. Lobefins evolved into the first amphibians that lived on both land and water.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-38","question":"About 15 million years ago, which primate was more man-like?","options":["Homo habilis","Ramapithecus","Dryopithecus","Australopithecus"],"answer":1,"explanation":"Ramapithecus and Dryopithecus existed about 15 mya; Ramapithecus was more man-like while Dryopithecus was more ape-like. Australopithecus and Homo habilis appeared much later.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-39","question":"How many of the following statements about embryological and molecular evidence are correct?\n(i) Embryological support for evolution was proposed by Ernst Haeckel.\n(ii) Karl Ernst von Baer disapproved it, noting that embryos never pass through the adult stages of other animals.\n(iii) Similarities in proteins and genes performing a given function among diverse organisms give clues to common ancestry.\n(iv) The gill slits developing in all vertebrate embryos, including humans, are functional organs.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Statements (i), (ii) and (iii) are correct. Vertebrate embryos develop vestigial gill slits behind the head, but they are functional only in fish.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-40","question":"Match the evolutionary concept with its description.\nList I: (A) Saltation (B) Adaptive radiation (C) Convergent evolution (D) Founder effect\nList II: (1) Unrelated groups evolve similar forms in similar habitats (2) Large single-step mutation causing speciation (3) Allele frequencies of a small migrant group differ from the original population by chance (4) Evolution of different species from one point, radiating into other habitats","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"De Vries called single-step large mutations saltation; Darwin's finches show adaptive radiation; Australian marsupials and placental mammals show convergent evolution; the founder effect is a case of genetic drift.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-41","question":"Assertion (A): Natural selection acts on heritable variation.\nReason (R): Darwin explained that this variation arises from mutations.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false: Darwin did not know the source of variation. Mutations were identified later by Hugo de Vries, who held that mutation, not minor variation, causes evolution.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-42","question":"A population of 1000 individuals has 490 AA, 420 Aa and 90 aa. Which statement is correct?","options":["p = 0.49, q = 0.09, and the population is not in equilibrium","p = 0.7, q = 0.3, but heterozygotes are in excess, so it is not in equilibrium","p = 0.6, q = 0.4, and the population is in equilibrium","p = 0.7, q = 0.3, and the population is in Hardy-Weinberg equilibrium"],"answer":3,"explanation":"p = (2 × 490 + 420)/2000 = 0.7 and q = 0.3. Expected frequencies p² = 0.49, 2pq = 0.42, q² = 0.09 match the observed 490 : 420 : 90, so the population is in equilibrium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-43","question":"How many of the following statements are correct?\n(i) Darwin made a sea voyage round the world in the ship HMS Beagle.\n(ii) Alfred Wallace came to similar conclusions while working in the Galapagos Islands.\n(iii) Darwin concluded that existing life forms share similarities with life forms that existed millions of years ago.\n(iv) Darwin explained evolution through the use and disuse of organs.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (iii) are correct. Wallace worked in the Malay Archipelago, and use and disuse of organs was Lamarck's explanation, not Darwin's.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-44","question":"Which of the following pairs is NOT homologous?","options":["Thorn of Bougainvillea and tendril of Cucurbita","Forelimbs of cheetah and whale","Eye of octopus and eye of mammals","Hearts of different vertebrates"],"answer":2,"explanation":"The eyes of octopus and mammals perform the same function but are anatomically different structures, so they are analogous (convergent evolution). The other pairs share a common origin (divergent evolution).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-45","question":"How many of the following statements are correct?\n(i) Excessive use of herbicides and pesticides has selected resistant varieties in a much shorter time scale.\n(ii) Evolution of antibiotic-resistant microbes happens on a time scale of years, not millions of years.\n(iii) A number of marsupials evolved from an ancestral stock within the Australian island continent.\n(iv) When more than one adaptive radiation appears in an isolated area, it can be called convergent evolution.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements; anthropogenic action is causing evolution, and placental mammals in Australia also show adaptive radiation that converges with the marsupials.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-evolution-46", "question": "The idea that giraffes evolved long necks by stretching to reach leaves, and passed this acquired character to their progeny, was proposed by:", "options": ["Hugo de Vries", "Lamarck", "Charles Darwin", "Alfred Wallace"], "answer": 1, "explanation": "Lamarck explained evolution by use and disuse of organs and inheritance of acquired characters, using the giraffe's neck as an example. Darwin explained evolution by natural selection.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-evolution-47", "question": "Analogous organs, such as the eye of the octopus and of mammals, are the result of:", "options": ["Saltation", "Genetic drift", "Divergent evolution", "Convergent evolution"], "answer": 3, "explanation": "Analogous structures perform similar functions but are not anatomically similar; they arise when different groups adapt to similar habitats, i.e. convergent evolution.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "bio-evolution-48", "question": "According to NCERT, the universe is about how old, and the earth was formed about when?", "options": ["2 billion years; 500 million years back", "20 billion years; 4.5 billion years back", "13 million years; 2 billion years back", "4.5 billion years; 20 million years back"], "answer": 1, "explanation": "The universe is described as almost 20 billion years old, and the earth was supposed to have been formed about 4.5 billion years back.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-evolution-49", "question": "The theory of special creation had three connotations. Which of the following was one of them?", "options": ["Mutations cause new species", "Life came from outer space as spores", "The earth is about 4000 years old", "Species evolve continuously by natural selection"], "answer": 2, "explanation": "Special creation held that all living organisms were created as such, that diversity was always the same since creation, and that the earth is about 4000 years old. Panspermia is a different idea.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-evolution-50", "question": "When a section of a population migrates to another place and population, the change in gene frequencies in both populations is called:", "options": ["Founder effect", "Genetic drift", "Gene flow (gene migration)", "Saltation"], "answer": 2, "explanation": "Gene migration changes gene frequencies in the old and the new population; when it happens many times it is called gene flow. Genetic drift is a change in gene frequency by chance.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-evolution-51", "question": "According to NCERT, the first mammals were like:", "options": ["Shrews", "Horses", "Kangaroos", "Elephants"], "answer": 0, "explanation": "NCERT states that the first mammals were like shrews, and their fossils are small sized. Mammals were viviparous and protected their unborn young inside the mother's body.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-evolution-52", "question": "The first organisms that invaded land were:", "options": ["Plants", "Reptiles", "Amphibians", "Fish with stout fins"], "answer": 0, "explanation": "NCERT notes that the first organisms to invade land were plants; they were widespread on land by the time animals invaded it.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-evolution-53", "question": "In a population in Hardy–Weinberg equilibrium, 36% of individuals show the DOMINANT phenotype. The frequency of the dominant allele is:", "options": ["0.8", "0.6", "0.2", "0.4"], "answer": 2, "explanation": "Recessive phenotype = 100% − 36% = 64%, so q² = 0.64 and q = 0.8. Then p = 1 − 0.8 = 0.2. Taking √0.36 = 0.6 directly as p is the trap, because 36% includes heterozygotes.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-54", "question": "According to NCERT, prehistoric cave art developed about:", "options": ["1,800 years ago", "18,000 years ago", "180,000 years ago", "1.8 million years ago"], "answer": 1, "explanation": "Pre-historic cave art developed about 18,000 years ago, and agriculture came around 10,000 years back with the start of human settlements.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-55", "question": "When South America joined North America, the pouched mammals of South America:", "options": ["Were overridden by North American fauna", "Remained unaffected", "Evolved into placental mammals", "Spread into North America and replaced placentals"], "answer": 0, "explanation": "NCERT notes that South American mammals resembling horse, hippopotamus, bear and rabbit (pouched forms) were overridden by North American fauna when the continents joined, while Australian pouched mammals survived because of lack of competition.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-56", "question": "Darwin's finches of the Galapagos evolved insectivorous and vegetarian forms from an original form that was:", "options": ["Fish-eating", "Nectar-feeding", "Seed-eating", "Insect-eating"], "answer": 2, "explanation": "From the original seed-eating features, many other forms with altered beaks arose, enabling them to become insectivorous and vegetarian finches; this is adaptive radiation.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-57", "question": "Similarities in the proteins and genes performing a given function among diverse organisms provide evidence for evolution because they:", "options": ["Prove that all organisms live in the same habitat", "Give clues to common ancestry", "Show that these organisms are analogous", "Prove the inheritance of acquired characters"], "answer": 1, "explanation": "Biochemical similarities such as similar proteins and genes for the same function point towards common ancestry, just as anatomical homology does.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-58", "question": "In collections of peppered moths made in England, before industrialisation (around 1850):", "options": ["Both forms were absent", "Only dark-winged moths existed", "Dark-winged moths were more common than white-winged moths", "White-winged moths were more common than dark-winged moths"], "answer": 3, "explanation": "Before industrialisation white-winged moths outnumbered dark ones; after industrialisation (1920) the proportion reversed, as dark moths were camouflaged on soot-covered, lichen-free tree trunks.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-59", "question": "NCERT describes evolution as a stochastic process because it is based on:", "options": ["Use and disuse of organs", "Chance events in nature and chance mutation in organisms", "A fixed plan of creation", "Inheritance of acquired characters"], "answer": 1, "explanation": "Evolution is a stochastic process based on chance events in nature and chance mutations in organisms, filtered by natural selection.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-evolution-60", "question": "How many of the following statements about reptiles and dinosaurs are correct?\n(i) Reptiles lay thick-shelled eggs that do not dry up in the sun, unlike those of amphibians.\n(ii) Some land reptiles went back into water to evolve into fish-like reptiles, probably about 200 million years ago (e.g. Ichthyosaurs).\n(iii) Dinosaurs suddenly disappeared from the earth about 65 million years ago.\n(iv) The biggest dinosaur, Tyrannosaurus rex, was about 100 feet in height.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct. (iv) is wrong: NCERT gives Tyrannosaurus rex a height of about 20 feet, with huge fearsome dagger-like teeth.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-61", "question": "Match the event with its approximate time.\nList I: (A) Formation of the earth (B) Appearance of life (C) Origin of the first non-cellular forms of life (D) Origin of the first cellular forms of life\nList II: (1) About 2000 million years ago (2) About 3 billion years ago (3) About 4.5 billion years ago (4) About 4 billion years ago", "options": ["A-3, B-4, C-2, D-1", "A-3, B-2, C-4, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-1, D-2"], "answer": 0, "explanation": "The earth formed about 4.5 billion years ago and life appeared about 500 million years later (about 4 billion years ago). Non-cellular life forms may have arisen about 3 billion years ago, and cellular forms only about 2000 million years ago.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-62", "question": "Assertion (A): Mutations are random and directionless.\nReason (R): Darwinian variations are small and directional.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both statements are true as given in NCERT, but R describes Darwinian variations; it does not explain why mutations are random, so R is not the explanation of A.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-63", "question": "In a population in Hardy–Weinberg equilibrium, 75% of individuals show the dominant phenotype. Among the individuals with the DOMINANT phenotype, what fraction is heterozygous?", "options": ["2/3", "3/4", "1/3", "1/2"], "answer": 0, "explanation": "q² = 0.25, so q = 0.5 and p = 0.5. AA = 0.25 and Aa = 2pq = 0.5. Among dominant-phenotype individuals: 0.5 ÷ 0.75 = 2/3. The 1/2 trap is the heterozygote fraction of the whole population.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-64", "question": "All of the following are examples of adaptive radiation EXCEPT:", "options": ["Australian marsupials radiating from an ancestral stock", "Darwin's finches of the Galapagos Islands", "Placental mammals of Australia diverging into many forms", "Industrial melanism in peppered moths"], "answer": 3, "explanation": "Adaptive radiation is evolution of different forms from one point into different habitats. Industrial melanism is a shift in the frequency of a variant under natural selection, not a radiation into many forms.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-65", "question": "Arrange the following in the order in which they evolved:\n(i) Reptiles (ii) Jawless fish (iii) Amphibians (iv) Mammals", "options": ["(iii), (ii), (i), (iv)", "(ii), (iii), (i), (iv)", "(ii), (iii), (iv), (i)", "(ii), (i), (iii), (iv)"], "answer": 1, "explanation": "Jawless fish evolved around 350 million years ago; lobefins gave rise to the first amphibians; amphibians gave rise to reptiles; and reptile ancestors later gave rise to mammals.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-66", "question": "How many of the following statements are correct?\n(i) Pouched mammals of Australia survived because of lack of competition from any other mammals.\n(ii) Australian marsupials evolved from an ancestral stock, all within the Australian island continent.\n(iii) When more than one adaptive radiation occurs in an isolated area representing different habitats, it is called convergent evolution.\n(iv) The placental wolf and the Tasmanian wolf resemble each other because they share a recent common ancestor.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iii) are correct, as stated in NCERT. (iv) is wrong: the two wolves resemble each other because of convergent evolution in similar habitats, not because of a recent common ancestor.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-67", "question": "Match the evolutionary concept with its example.\nList I: (A) Divergent evolution (B) Convergent evolution (C) Adaptive radiation (D) Evolution by anthropogenic action\nList II: (1) Eye of the octopus and of mammals (2) Antibiotic-resistant microbes (3) Darwin's finches (4) Hearts and brains of vertebrates", "options": ["A-1, B-4, C-3, D-2", "A-4, B-1, C-3, D-2", "A-3, B-1, C-4, D-2", "A-4, B-1, C-2, D-3"], "answer": 1, "explanation": "Vertebrate hearts and brains are homologous (divergent evolution); octopus and mammal eyes are analogous (convergent); Darwin's finches show adaptive radiation; antibiotic-resistant microbes evolved under human action.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-68", "question": "Assertion (A): Lichens can be used as indicators of industrial pollution.\nReason (R): Lichens do not grow in polluted areas.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Because lichens fail to grow in polluted areas, their absence signals pollution; in industrial England, lichen-free, soot-covered trunks favoured dark moths.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-69", "question": "How many of the following statements about the evolution of modern humans are correct?\n(i) Homo sapiens arose in Africa and moved across continents.\n(ii) During the ice age between 75,000 and 10,000 years ago, modern Homo sapiens arose.\n(iii) Pre-historic cave art developed about 18,000 years ago.\n(iv) Agriculture came around 10,000 years back, along with human settlements.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct NCERT statements on the later stages of human evolution.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-evolution-70", "question": "A recessive disorder affects 1 in 10,000 people in a population in Hardy–Weinberg equilibrium. The approximate frequency of carriers (heterozygotes) is:", "options": ["1 in 100", "1 in 50", "1 in 5000", "1 in 200"], "answer": 1, "explanation": "q² = 1/10,000, so q = 0.01 and p ≈ 0.99. Carriers = 2pq = 2 × 0.99 × 0.01 ≈ 0.0198, about 1 in 50. 1 in 100 is the allele frequency q, a common trap.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-evolution-71","question":"Some land reptiles went back into water about 200 million years ago and evolved into fish-like reptiles. An example of such reptiles is:","options":["Pelycosaurs","Lobefins","Ichthyosaurs","Coelacanths"],"answer":2,"explanation":"NCERT cites Ichthyosaurs as land reptiles that returned to water and became fish-like around 200 mya. Lobefins and the coelacanth are fishes, not reptiles that went back to the sea.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-evolution-72","question":"According to NCERT, which group consists only of mammals that live wholly in water?","options":["Whales, penguins, seals and turtles","Dolphins, sharks, sea cows and seals","Seals, crocodiles, whales and dolphins","Whales, dolphins, seals and sea cows"],"answer":3,"explanation":"Whales, dolphins, seals and sea cows are the mammals NCERT lists as living wholly in water. Penguins are birds, sharks are fishes, and turtles and crocodiles are reptiles.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-evolution-73","question":"The first human-like being, the hominid, is named:","options":["Homo habilis","Homo erectus","Dryopithecus","Homo sapiens neanderthalensis"],"answer":0,"explanation":"About 2 mya, Homo habilis was the first human-like being (hominid), with a brain of 650–800 cc. Dryopithecus was an ape-like primate, and Homo erectus came later, about 1.5 mya.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-evolution-74","question":"Alfred Wallace independently reached conclusions similar to Darwin's on natural selection while working as a naturalist in the:","options":["Malay Archipelago","Galapagos Islands","Australian continent","West Indies"],"answer":0,"explanation":"Wallace worked in the Malay Archipelago. Darwin's observations came from the voyage of HMS Beagle, including the Galapagos Islands, so that option is the common mix-up.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-75","question":"Which of these hominids used hides to protect their bodies and buried their dead?","options":["Homo habilis","Neanderthal man","Australopithecines","Ramapithecus"],"answer":1,"explanation":"NCERT notes that Neanderthal man (about 1400 cc brain, 1,00,000–40,000 years ago) used hides for protection and buried their dead. Australopithecines hunted with stone weapons but ate mainly fruit.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-76","question":"A trait shows a bell-shaped distribution in a population. Over several generations the peak shifts toward one extreme while keeping its single-peaked shape. This is:","options":["Stabilising selection","Disruptive selection","Directional selection","Genetic drift by founder effect"],"answer":2,"explanation":"In directional selection, individuals at one end (a value other than the mean) are favoured, so the peak moves in that direction. Stabilising selection narrows the curve around the mean; disruptive selection produces two peaks.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-77","question":"According to NCERT, invertebrates were formed and active by about 500 million years ago, and jawless fish probably evolved around:","options":["200 million years ago","65 million years ago","2000 million years ago","350 million years ago"],"answer":3,"explanation":"NCERT places jawless fish at about 350 mya. 200 mya is when Ichthyosaurs went back to water, 65 mya is when dinosaurs disappeared, and 2000 mya is the appearance of the first cellular life.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-78","question":"In population genetics, a change in the frequency of alleles in the gene pool, which disturbs genetic equilibrium, is interpreted as:","options":["Genetic stability","Evolution","Hardy–Weinberg equilibrium","Absence of selection"],"answer":1,"explanation":"Hardy–Weinberg states that allele frequencies stay constant from generation to generation. When this equilibrium is disturbed and frequencies change, the population is said to be evolving.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-79","question":"Fossils discovered in Java in 1891 revealed which stage of human evolution, dated to about 1.5 million years ago?","options":["Homo habilis","Neanderthal man","Homo erectus","Australopithecus"],"answer":2,"explanation":"The Java fossils (1891) revealed Homo erectus, about 1.5 mya, with a brain of about 900 cc. Homo habilis lived about 2 mya with a smaller brain of 650–800 cc.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-evolution-80","question":"Which statement about Homo habilis is consistent with NCERT?","options":["Its brain capacity was about 900 cc and it probably ate meat","It buried its dead and used hides to protect the body","It arose in Africa during the last ice age, 75,000–10,000 years ago","Its brain capacity was 650–800 cc and it probably did not eat meat"],"answer":3,"explanation":"Homo habilis had a 650–800 cc brain and probably did not eat meat. A 900 cc brain with meat-eating describes Homo erectus, burial of the dead describes Neanderthals, and the ice-age origin describes Homo sapiens.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-81","question":"When reptiles came to dominate the land, the giant ferns (pteridophytes) present at that time:","options":["All fell and slowly formed coal deposits","Evolved directly into angiosperms","Were the first plants to invade land","Became the ancestors of seaweeds"],"answer":0,"explanation":"NCERT states that the giant ferns of that era all fell and slowly formed coal deposits. The first land invaders were plants, but not these giant ferns, and seaweeds existed long before them.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-82","question":"In experiments similar to Miller's, other scientists observed the formation of several organic compounds. Which of these was NOT among them?","options":["Self-replicating living cells","Sugars","Nitrogen bases","Pigments and fats"],"answer":0,"explanation":"Others obtained sugars, nitrogen bases, pigments and fats; Miller himself got amino acids. No such experiment produced a living cell, so these experiments support chemical evolution only, not the creation of life.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-83","question":"A bacterial colony with built-in variation is moved to a new medium, and within days a variant population outgrows the others. The same change could take millions of years in fish or fowl mainly because:","options":["Fish and fowl do not show any heritable variation","Their life spans, and so generation times, run into years","Natural selection does not act on multicellular animals","Mutations occur only in prokaryotes"],"answer":1,"explanation":"The rate of evolution depends on generation time: bacteria divide in minutes, while fish and fowl live for years. All organisms show heritable variation and are subject to natural selection, so the other options are false.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-84","question":"When more than one adaptive radiation appears to have occurred in an isolated geographical area representing different habitats, the process can be called:","options":["Divergent evolution","Genetic drift","Convergent evolution","Saltation"],"answer":2,"explanation":"NCERT calls this convergent evolution, illustrated by Australian marsupials and placental mammals that came to resemble each other. Divergent evolution produces homologous structures from one ancestral plan.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-85","question":"In a population of 500 snapdragon plants (flower colour shows incomplete dominance), there are 245 red, 210 pink and 45 white plants. The frequency of the allele for red colour is:","options":["0.49","0.6","0.3","0.7"],"answer":3,"explanation":"Because each genotype has its own phenotype, alleles can be counted directly: red alleles = 2 × 245 + 210 = 700 out of 1000, so p = 0.7. 0.49 is the red genotype frequency (p²), and 0.3 is the white allele frequency.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-86","question":"For a gene with two alleles in a population in Hardy–Weinberg equilibrium, the highest possible frequency of heterozygotes is:","options":["25%","50%","75%","100%"],"answer":1,"explanation":"The heterozygote frequency 2pq reaches its maximum when p = q = 0.5, giving 2 × 0.5 × 0.5 = 0.5. 25% is the frequency of each homozygote at that point, not of the heterozygotes.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-87","question":"Man-like bone fossils from Ethiopia and Tanzania suggest that about 3–4 million years ago man-like primates in eastern Africa:","options":["Were about 6 feet tall and walked on all fours","Had a brain of about 1400 cc and buried their dead","Were probably not taller than 4 feet but walked upright","Made cave paintings and practised agriculture"],"answer":2,"explanation":"According to NCERT, these primates were probably no taller than 4 feet but walked upright. A 1400 cc brain and burial fit Neanderthals; cave art (about 18,000 years ago) and agriculture (about 10,000 years ago) came much later.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-88","question":"Ernst Haeckel proposed embryological support for evolution from features, such as gill slits, that are common to vertebrate embryos but absent in adults. Karl Ernst von Baer disproved this by noting that:","options":["Gill slits are absent in all mammalian embryos","Embryos of different vertebrates show no common features","Embryonic features are acquired characters and are not inherited","Embryos never pass through the adult stages of other animals"],"answer":3,"explanation":"Von Baer showed that embryos never pass through the adult stages of other animals. He did not deny the shared embryonic features; even the human embryo has a row of vestigial gill slits.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-89","question":"How many of the following pairs are homologous?\n(i) Hearts of different vertebrates\n(ii) Thorn of Bougainvillea and tendril of Cucurbita\n(iii) Wings of a butterfly and of a bird\n(iv) Sweet potato and potato\n(v) Brains of different vertebrates","options":["Two","Three","Four","Five"],"answer":1,"explanation":"Vertebrate hearts, vertebrate brains, and the thorn of Bougainvillea with the tendril of Cucurbita are homologous: (i), (ii) and (v). The insect and bird wings, and the sweet potato (root) with the potato (stem), are analogous.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-90","question":"According to NCERT, which statement about the disappearance of dinosaurs about 65 million years ago is correct?","options":["The true reason is not known; climatic change and evolution of most of them into birds are both suggested","They were all killed by a meteorite impact, which is proved","They evolved directly into the first mammals","They were wiped out by competition from placental mammals"],"answer":0,"explanation":"NCERT says the true reason is not known: some suggest climatic changes, others that most evolved into birds, and the truth may lie in between. Mammals had appeared earlier, and nothing in NCERT proves a single cause.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-evolution-91","question":"A population of 1000 individuals has 400 AA, 400 Aa and 200 aa. Compared with the genotype numbers expected under Hardy–Weinberg equilibrium for the same allele frequencies, the population has:","options":["Exactly the expected numbers, so it is in equilibrium","Fewer heterozygotes than expected, so it is not in equilibrium","More heterozygotes than expected, so it is not in equilibrium","Fewer homozygous recessives than expected, so it is not in equilibrium"],"answer":1,"explanation":"p = (800 + 400)/2000 = 0.6 and q = 0.4, so the expected numbers are 360 AA, 480 Aa and 160 aa. The observed 400 Aa is below 480 and both homozygote classes are in excess, so the population is not in equilibrium.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-92","question":"In a population in Hardy–Weinberg equilibrium, 10% of males show an X-linked recessive trait. The expected percentage of females showing the trait is:","options":["10%","5%","1%","20%"],"answer":2,"explanation":"Males have one X, so the affected male frequency equals the allele frequency: q = 0.1. Females need two copies, so q² = 0.01, or 1%. This is why X-linked recessive traits are much commoner in males.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-93","question":"In a population in Hardy–Weinberg equilibrium the frequency of a recessive allele is 0.2. The ratio of heterozygotes to homozygous recessive individuals is:","options":["4 : 1","2 : 1","16 : 1","8 : 1"],"answer":3,"explanation":"Heterozygotes = 2pq = 2 × 0.8 × 0.2 = 0.32 and recessives = q² = 0.04, so the ratio is 0.32/0.04 = 8. Most copies of a rare recessive allele are therefore hidden in carriers.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-94","question":"Arrange the following in the order in which they appeared, from earliest to latest, according to NCERT:\n(i) Jawless fish\n(ii) First cellular forms of life\n(iii) Seaweeds and a few plants\n(iv) Active invertebrates","options":["(ii), (iii), (iv), (i)","(iv), (ii), (i), (iii)","(ii), (i), (iv), (iii)","(ii), (iv), (i), (iii)"],"answer":3,"explanation":"NCERT dates are: cellular life about 2000 mya, invertebrates active by 500 mya, jawless fish about 350 mya, and seaweeds and a few plants about 320 mya. Seaweeds are the trap: they are dated after the jawless fish.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-95","question":"Match the hominid with its period.\nList I: (A) Australopithecines (B) Homo erectus (C) Neanderthal man (D) Modern Homo sapiens arising in Africa\nList II: (1) About 1.5 million years ago (2) About 2 million years ago (3) 75,000–10,000 years ago (4) 1,00,000–40,000 years ago","options":["A-1, B-2, C-4, D-3","A-2, B-1, C-3, D-4","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"answer":2,"explanation":"Australopithecines lived about 2 mya and Homo erectus about 1.5 mya. Neanderthals lived 1,00,000–40,000 years ago, and modern Homo sapiens arose during the ice age, 75,000–10,000 years ago.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-96","question":"How many of the following statements are correct?\n(i) Darwin's finches show adaptive radiation from an original seed-eating form.\n(ii) Australian marsupials radiated from an ancestral stock within the Australian continent.\n(iii) Placental mammals in Australia also show adaptive radiation.\n(iv) The flying phalanger and the flying squirrel are homologous organisms of common descent.\n(v) The Tasmanian wolf and the placental wolf illustrate convergent evolution.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. The flying phalanger (a marsupial) and the flying squirrel (a placental) resemble each other through convergent evolution, not close common descent, so (iv) is wrong.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-97","question":"Two populations are each in Hardy–Weinberg equilibrium for the same gene. In population X the dominant allele frequency is 0.9; in population Y it is 0.5. The heterozygote frequency in Y is about how many times that in X?","options":["Equal in both","1.8 times","2.8 times","5 times"],"answer":2,"explanation":"X: 2pq = 2 × 0.9 × 0.1 = 0.18. Y: 2pq = 2 × 0.5 × 0.5 = 0.50. 0.50/0.18 ≈ 2.8. Heterozygosity is highest when the two alleles are equally common.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-98","question":"Assertion (A): Evolution by natural selection, in the true sense, would have begun only when cellular forms of life differing in metabolic capability arose on Earth.\nReason (R): Natural selection can act only on heritable differences that affect survival and reproduction.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCERT states (A). Selection needs heritable variation in fitness, which appeared when cells differing in metabolism arose, so (R) explains (A).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-99","question":"Assertion (A): Lamarck's explanation that giraffes got long necks by stretching is not accepted today.\nReason (R): Changes acquired by body (somatic) cells during an organism's life do not alter the genes passed on through gametes.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Lamarck's idea depends on inheriting acquired characters. Somatic changes do not reach the germ-line DNA, so stretched necks cannot be inherited. (R) therefore explains why (A) is true.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-evolution-100","question":"A recessive disorder has an allele frequency of 0.1 in a population in Hardy–Weinberg equilibrium. Two unrelated, phenotypically normal people from this population marry. The probability that their first child is affected is:","options":["1/100","1/400","1/121","1/44"],"answer":2,"explanation":"P(carrier | normal) = 2pq/(1 − q²) = 0.18/0.99 = 2/11. Both parents must be carriers and the child must be aa: (2/11)² × 1/4 = 1/121. Using 2pq = 0.18 for each parent without excluding affected people gives the trap of about 1/123.","difficulty":"very-hard","source":"NEET pattern"},
];

export default questions;
